API Gateway (Envoy).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway (Envoy)") {
    Component(mtls_termination_and_routing, "mTLS Termination and Routing", "Envoy C++", "Handles mTLS termination, local rate limiting, and circuit breaking for incoming traffic.")
    Component(grpc_proxy, "gRPC Proxy", "Envoy HTTP/2", "Forwards scoring requests to the Real-Time Scoring Engine via gRPC/HTTP2.")
    Component(https_proxy, "HTTPS Proxy", "Envoy HTTPS", "Routes administrative and analyst traffic to the Case Management Backend.")
}

Rel(mtls_termination_and_routing, grpc_proxy, "Forwards payment scoring requests", "gRPC/HTTP2")
Rel(mtls_termination_and_routing, https_proxy, "Forwards analyst traffic", "HTTPS")
@enduml

Redis (ElastiCache).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(redis_elasticache, "Redis (ElastiCache)") {
    Component(Feature_Cache, "Feature Cache", "Redis Hash and String Data Structures", "Caches low-latency features and behavioral data using volatile-lru eviction policy.")
    Component(Snapshot_Exporter, "Snapshot Exporter", "AWS ElastiCache RDB Export", "Exports automated daily RDB snapshots to AWS S3.")
}

Rel(Feature_Cache, Snapshot_Exporter, "Triggers automated daily backups", "")

@enduml

Amazon SQS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon SQS container

Container_Boundary(amazon_sqs, "Amazon SQS") {
    Component(fraud_audit_events_queue, "fraud-audit-events-queue", "Amazon SQS Standard Queue", "Decouples scoring from audit logging to protect P99 latency and buffer audit events.")
    Component(fraud_audit_events_dlq, "fraud-audit-events-dlq", "Amazon SQS Dead Letter Queue", "Captures and stores undeliverable or failed audit events for troubleshooting and compliance.")
}

Rel(fraud_audit_events_queue, fraud_audit_events_dlq, "Routes permanently failed messages after max retries")

@enduml
